endpoint.response:
{ success: true, message: "OK", data: { applied: { date_from: string|null, date_to: string|null, company_id: int[], company_site_id: int[], operational_site_id: int[], business_function_id: int[], work_order_type: string[], commercial_id: int[], revenue_basis: string, segment_by: string }, totals: Figures & { work_orders_count: int }, (tutte le commesse selezionate) by_business_function: FunctionRow[], (sempre; una per funzione, ordinate per label; "unattributed" ultimo) segments: SegmentRow[] (vuoto con segment_by = none; una per valore del segmento, ordinate per label; "unattributed" ultimo) } }
Figures = { revenue_contract: number, (somma LineEffectiveRevenue delle righe REVENUE assegnate) revenue_invoiced: number, (somma invoices.net_amount, type = invoice, work_order_id = commessa) revenue_collected: number, (D-13) revenue_actual: number, (= revenue_contract | revenue_invoiced | revenue_collected secondo revenue_basis) cost_budget: number, (righe COST allocate alle righe della commessa, 0190 D-1) cost_manual: number, (work_order_costs.net_amount, tutte) cost_committed: number, (ODA impegnato netto del fatturato, D-14) cost_invoiced: number, (purchase_invoice_lines.net_amount con work_order_id = commessa) cost_actual: number, (= cost_manual + cost_committed + cost_invoiced) commission_budget: number, (D-8) commission_actual: number, (D-8, puo' essere negativa in presenza di soli storni) margin_budget: number, (= revenue_contract - cost_budget - commission_budget) margin_actual: number, (= revenue_actual - cost_actual - commission_actual) cost_delta: number, (= cost_actual - cost_budget; positivo = sforamento) margin_delta: number (= margin_actual - margin_budget) }
FunctionRow = { key: string, (id della funzione aziendale come stringa; "unattributed") label: string | null, (business_functions.name; null per "unattributed", D-19) work_orders_count: int, (commesse con almeno una riga in quella funzione, D-23) ...Figures (ripartite per funzione, D-11) }
SegmentRow = { key: string, (id della dimensione come stringa; valore enum per work_order_type; "unattributed") label: string | null, (nome; null per "unattributed" e per work_order_type, D-19) work_orders_count: int, (commesse del segmento) ...Figures, (somme intere delle commesse del segmento) by_business_function: FunctionRow[] (il prospetto per funzione delle sole commesse del segmento) }
Importi: number con 2 decimali, imponibile (D-6), calcolati in centesimi interi. Invarianti: somma di by_business_function = totals campo per campo (il residuo di arrotondamento della ripartizione va sull'ultima quota); somma dei segments = totals; in ogni segmento la somma del suo by_business_function = le cifre del segmento. I conteggi delle funzioni NON si sommano (D-23).

{ success: true, message: "OK", data: {
    applied: { date_from, date_to, company_id: int[], company_site_id: int[], operational_site_id: int[], group_by: string },
    totals: StructureFigures,
    by_cost_type: StructureCostTypeRow[],   (ordine cost_types.sort_order, name, id; senza tipo ultimo)
    by_dimension: StructureDimensionRow[]   (ordinate per label; "non attribuito" ultimo)
} }

StructureFigures = { committed_net: number, invoiced_net: number, total_net: number }
StructureCostTypeRow = {
  cost_type: { id: int, name: string, color: string|null, nature: "direct"|"indirect"|"general"|null } | null,
  ...StructureFigures
}
StructureDimensionRow = { key: string, label: string | null, ...StructureFigures }
